const send = (res, asset, cache = "public, max-age=86400") => {
  res.setHeader("Content-Type", asset.type);
  res.setHeader("Cache-Control", cache);
  res.send(Buffer.from(asset.b64, "base64"));
};

app.get("/style.css", (_req,res) => send(res,assets.css));
app.get("/app.js", (_req,res) => send(res,assets.js,"no-cache"));
app.get("/api/logo", (_req,res) => send(res,assets.logo,"public, max-age=31536000, immutable"));
app.get("/api/hero-bg", (_req,res) => send(res,assets["hero-bg"]));
app.get("/api/hero-desktop", (_req,res) => send(res,assets["hero-desktop"]));
app.get("/api/menu-photo", (req,res) => {
  const file = photoMap[String(req.query.kind || "")];
  const asset = file && assets["photo:" + file];
  if (!asset) return res.status(404).send("not found");
  send(res,asset,"public, max-age=31536000, immutable");
});
app.get("/health", (_req,res) => res.json({ok:true}));

let pool;
if (process.env.DATABASE_URL) pool = new pg.Pool({connectionString:process.env.DATABASE_URL,ssl:process.env.NODE_ENV==="production"?{rejectUnauthorized:false}:false});
if (pool) pool.query(`CREATE TABLE IF NOT EXISTS orders (
  id UUID PRIMARY KEY, order_number BIGSERIAL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  customer_name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, details TEXT,
  payment TEXT NOT NULL, comment TEXT, items JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'new'
)`).catch(console.error);
const esc = value => String(value ?? "").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));

app.post("/api/order", async (req,res) => {
  try {
    const b=req.body||{}; const items=Array.isArray(b.items)?b.items.slice(0,100):[];
    if(!b.name||!b.phone||!b.address||!items.length) return res.status(400).json({error:"Заполните имя, телефон, адрес и добавьте блюда"});
    const safeItems=items.map(x=>({name:String(x.name||"").slice(0,150),quantity:Math.max(1,Math.min(50,Number(x.quantity)||1))}));
    let orderNumber=String(Date.now()).slice(-8);
    if(pool){const result=await pool.query("INSERT INTO orders (id,customer_name,phone,address,details,payment,comment,items) VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb) RETURNING order_number",[crypto.randomUUID(),String(b.name).slice(0,120),String(b.phone).slice(0,80),String(b.address).slice(0,300),String(b.details||"").slice(0,300),String(b.payment||"Не указан").slice(0,100),String(b.comment||"").slice(0,1000),JSON.stringify(safeItems)]);orderNumber=String(result.rows[0].order_number)}
    if(process.env.SMTP_HOST&&process.env.SMTP_USER&&process.env.SMTP_PASS&&process.env.ORDER_EMAIL){
      const transport=nodemailer.createTransport({host:process.env.SMTP_HOST,port:Number(process.env.SMTP_PORT||465),secure:String(process.env.SMTP_SECURE||"true")==="true",auth:{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS}});
      const list=safeItems.map(x=>`<li>${esc(x.name)} — ${x.quantity} шт.</li>`).join("");
      await transport.sendMail({from:process.env.SMTP_FROM||process.env.SMTP_USER,to:process.env.ORDER_EMAIL,subject:`Новый заказ РопиРолл №${orderNumber}`,html:`<h2>Новый заказ №${orderNumber}</h2><p><b>Имя:</b> ${esc(b.name)}<br><b>Телефон:</b> ${esc(b.phone)}<br><b>Адрес:</b> ${esc(b.address)}<br><b>Детали:</b> ${esc(b.details||"—")}<br><b>Оплата:</b> ${esc(b.payment||"—")}<br><b>Комментарий:</b> ${esc(b.comment||"—")}</p><ul>${list}</ul>`});
    } else console.log("NEW_ORDER",JSON.stringify({orderNumber,...b,items:safeItems}));
    res.json({ok:true,orderNumber});
  } catch(error){console.error(error);res.status(500).json({error:"Не удалось отправить заказ"})}
});
app.use((_req,res)=>send(res,assets.index,"no-cache"));
app.listen(port,"0.0.0.0",()=>console.log(`РопиРолл запущен на порту ${port}`));
